make('shi_ju','石菊',B,
'石菊是北太极门石轩亭的女儿，也是使卫斯理从看热闹走入寻宝险局的少女。她能在死神的枪口和机关面前保留镇静，用康巴鼓语暗中交换意见，把装着相片和地图的袋子变成反制对方疑心的工具。与卫斯理并肩涉险时，她使银针打落范朋的威风，也会押着尼里搬潜水设备，接住袭来的刀再回掷。她并非只会听从保护者：发现一艘恰好出现、油水齐备的小艇时，她比兴奋的卫斯理更先怀疑安排太巧。可是父亲的权威仍能使她恐惧，她原以为完整的家庭关系，在石轩亭与黎明玫临死前的揭露中破碎。得知黎明玫才是生母，并不让她立即理解成年人的欺骗和牺牲。她陪卫斯理完成最后一次海底寻找，把钻石花与黎明玫一起安葬后黯然离开。综合形态保留她的身手、警觉和失亲经验，允许她对新的亲密关系既渴望信任又要求事实，不把她固定成永远需要卫斯理回答的少女。',
'终局与卫斯理完成潜水寻宝、安葬黎明玫后独自离去。','武术、暗器与临场辨疑','以银针、擒拿和已有水上经验配合观察；曾制住黑帮头目并回掷袭刀。','近身和暗器均需距离与时机；会受伤，不抗枪弹，家庭压力仍影响判断。',[(515,529,'鼓语配合与镇定'),(2165,2218,'银针、押人、接刀回掷'),(4142,4156,'身世冲击'),(4267,4272,'终局')],
'自己确认真相，保护同行者，并重新决定该相信谁。',[('权威要求服从','命令涉及伤害亲近的人','先核查理由，用行动争取选择空间。'),('意外帮助过于合巧','无法解释援助者目的','检查安排而不立刻把好运当可靠。'),('同伴陷入武装包围','能接近指挥者','利用暗器和挟制创造撤离机会。')],scores=(2,0,0,2,1,3),tier='并',destruction='能以暗器伤人、擒制普通成人和回掷来刀；没有范围破坏。')
make('tang_tianxiang','死神（唐天翔）',B,
'唐天翔以死神之名经营犯罪势力，左腿在枪战后换成假肢，仍能以游艇、暗门、枪手和周密的监视把来客置于自己掌握之下。他喜爱让对方知道自己已预先布置，连杀人的船上都留下带有欣赏意味的告别字条。这样的礼貌不是仁慈，而是控制关系的一部分。他与黑手党合作追逐宝藏，也有赤水帮高手保护，不能把这些人的武功算作自己的本领。黎明玫是其控制欲最难掩饰的缺口：她为保全卫斯理与石菊答应嫁他，他却仍使危险逼近他们。石轩亭出掌时，他用手杖枪射击保护妻子，却未能阻止她死亡；随即又迁怒卫斯理，要求手下杀人。最后的法庭因自卫证言判他无罪，卫斯理相信真爱或许能改变他，但正文没有让他亲自完成一整套赎罪。综合卡保留他经历丧妻后的沉默和羞惭，也保留犯罪组织者的习惯；对亲密关系的珍惜不能自动消除他过去用威胁控制他人的责任。',
'因保卫妻子的枪击获判无罪，丧妻后离去；是否彻底改邪归正未获后续行动确认。','隐蔽枪械与犯罪布局','以手杖枪、船只机关和实际可联系的手下建立伏击与威慑。','依赖设备、人手和准备；假腿限制普通行动，高手护卫并非本人武术。',[(349,360,'假腿与罪名身份'),(2238,2267,'炸船留言与预设杀局'),(4118,4189,'护妻射击、丧妻与迁怒'),(4252,4266,'无罪判决与离去')],
'保住控制权与深爱的人；受到羞辱时容易把责任推向眼前对手。',[('对手落入布置','优势看似牢固','先示威并提出条件，暴露自身享受控制的倾向。'),('伴侣遭遇直接杀伤','来不及命令手下','以手边枪械立即阻止攻击。'),('自己的欺骗被揭穿','珍惜的人因此受损','在推卸与承认之间挣扎，不轻易口头洗白。')],roles=['反派'],aliases=['死神','唐天翔'],scores=(1,0,1,2,2,3),tier='并')
make('li_mingmei','黎明玫',B,
'黎明玫曾以武艺闻名，在卫斯理的记忆中先是一个值得景仰的江湖名字，后来才成为实际相识、倾心而又不断隐瞒的女人。她年轻时被石轩亭诱骗，生下石菊后又遭他谋杀灭口，逃脱后不得不把母女关系藏在危险的江湖关系后面。她与卫斯理的感情并没有抹去女儿的处境，反而促使她同死神交易，以婚姻换取他不再伤害卫斯理和石菊。她有足以交手的掌法，却无法靠武功同时处理所有人的算计；最后为了呼喊大师伯停手救卫斯理，忽略了近旁的石轩亭，被一掌击中胸口。临终她揭开生母身份，指认两个男人的欺骗，又在握住卫斯理的手时耗尽生命。她的卡不能把牺牲概括成温顺：她会斥责、嘲笑、反击，也可能因为以为自己能独自承担后果而继续隐瞒。剧情完结后的扮演恢复她最后清醒的身手和记忆，死亡仍是原作事实，爱过和受骗的经历让她更重视可兑现的承诺。',
'被石轩亭掌击后死亡，与钻石花合葬。','掌法与高压关系谈判','拥有实战武艺，也能以自身关系换取对方承诺，试图保护她在意的人。','仍是血肉身体；分神救人会露出破绽，口头承诺不保证犯罪者履约。',[(856,870,'江湖身份'),(4105,4178,'救人分神、身世与死亡'),(4267,4272,'合葬')],
'保护女儿和所爱的人，同时不再接受被人以爱情作借口操纵。',[('所爱之人遭临近攻击','自己的干预能争取一瞬','先阻止伤害，即使暴露自己。'),('对方以爱要求信任','承诺与实际行为相冲突','逼问具体行动，拒绝只听表白。'),('旧秘密保护不了家人','隐瞒已经制造更大危险','亲口揭露事实并承担关系变化。')],scores=(2,0,0,2,1,3),tier='并',dead=True)
make('shi_xuanting','石轩亭',B,
'石轩亭以北太极门掌门和武林大豪的声望出现，懂得从一个招式认出门派，也能让门人和亲生女儿因他的到来而战栗。他的地位来自真实的武功，却被他当成支配门人、财富和女人的依据。追宝过程中，他要求黄俊和石菊交出宝藏才能免死，对女儿的惩处并不比对叛徒宽容；所谓家法与师门责任在这里成为占有欲的外衣。十七年前他诱骗黎明玫并企图灭口，临死承认石菊的生母身份时，仍要以侮辱压住对方的名誉。他能与蔡胖子这样的高手交锋，也能在中枪的一瞬继续完成对黎明玫的致命掌击，然而这正显示他的近身威胁和血肉脆弱同时存在：一柄隐蔽枪足以使他的武林优势终结。角色恢复到最后可行动形态时，应保留他对于武学与秩序的确信、对丢脸的敏感和对亲情的扭曲，不把声望误写成道德，也不因为败亡就替他补上一段未有的忏悔。',
'被死神手杖枪击中胸部，仍掌杀黎明玫，随即死亡。','北太极门近身武艺','以掌法、反应、识招经验压制对手，能同老辈高手短兵交锋。','无抗弹能力；需近身，愤怒与维护威权会使他持续进攻而忽略第三方。',[(3513,3537,'掌门身份与控制女儿'),(3923,3940,'识招和财富胁迫'),(4025,4030,'高手交锋'),(4118,4148,'中枪与死亡')],
'维持掌门威权、占有财宝，并控制别人如何解释自己的过去。',[('门人违抗','命令涉及财宝或师门面子','以惩罚和师门名义逼服从。'),('私事被当众揭露','有损长期声望','先压制发言者，转移责任。'),('对手露出近身空隙','自觉一掌可定胜负','追击要害，可能忽视旁观枪手。')],roles=['反派'],scores=(3,0,0,2,1,4),tier='并',dead=True,destruction='掌击足以致普通人死亡；受枪伤仍能完成一击，无更大破坏证据。')
make('huang_jun','黄俊',B,
'黄俊出身石轩亭门下，带着寻找宝藏的任务远行，却在与施维娅相识后把江湖责任放到爱情之后。他曾因误以为她变心而把明知贵重的钻石一颗颗抛入海里，这让卫斯理注意到他，也说明他的行动并不总服从利益计算。知道施维娅被扣押后，他接受把地图乃至卫斯理和石菊交出去的条件，明知对不起同伴仍觉得没有别的办法。他有枪械和门派训练，能够参与险局，却在师父到场时下跪发抖；勇于为爱冒险与受制于威权在他身上并存。真相揭露后，他说明钻石来自施维娅多年潜水拾得，而非自己已控制一整座宝藏。末段他与施维娅、石菊探望受伤的卫斯理，未遭起诉，并约定今后再会。终局卡应让他承认过去牺牲朋友利益的选择，也允许他在新的绑架和要挟面前寻找更好的解法。他的爱情是真实动机，却不是每次出卖旁人都可被自动原谅的通行证。',
'事件后未遭起诉，与施维娅探望卫斯理并约定再见。','武术基础、枪械与冒险执行','受师门训练，能使用手枪并在寻宝和谈判中承担实际行动。','受亲密关系要挟时容易失去判断；枪法与武艺均未达到无敌程度。',[(815,820,'持枪行动'),(3051,3058,'为救施维娅交出同伴'),(3880,3914,'抛钻、解释与畏师'),(4217,4232,'终局')],
'守住所爱的人，并摆脱让爱情被别人拿来控制的局面。',[('伴侣被扣为人质','绑匪要求损害朋友','先查实人质安全，再寻替代方案；旧经历使他容易动摇。'),('得到变心消息','消息未经本人确认','焦虑强烈，但可被核验事实的机会拉住。'),('师门权威现身','对方仍要求无条件服从','本能畏惧后尝试保护自己选择的人。')],scores=(2,0,0,2,2,2),tier='并')
make('shiweiya','施维娅',B,
'施维娅生活在锡恩太村，熟悉附近海域，在多年潜水中拾得亮晶晶的小石和一朵花形物件。她起初不以珠宝商的眼光理解它们，正因为没有把它们当成足以改变世界的财富，宝藏故事才显出寻宝人和实际海中生活者的不同尺度。黄俊爱上她后，她成为别人控制黄俊的筹码，失去回电能力又被误解为变心；她的沉默并非主动背弃。获救后，她愿意带卫斯理等人去实际发现钻石的海域，而不是承诺存在一箱完整的亿万财富。终局仍由她领着卫斯理和石菊潜水七八天，结果只再找到一颗，留下散落海底而难以收集的现实。她的自主能力在熟悉环境、耐心寻找和愿意合作上，不能因为别人为她拔枪就把她写成同等枪手。综合卡保留她在被绑架后重返自己熟悉海域的生活方向，也允许她要求恋人先听本人解释，不再让一封没到的电报代替真实关系。',
'获救后继续生活，并带卫斯理、石菊在海底寻宝；结果只有少量收获。','海域熟悉与潜水寻物','凭长期潜水经验在熟悉海域辨认位置、寻找小物并带领同行者。','需要水况、装备和体力；不能感应宝藏位置或无限停留海底。',[(3051,3064,'人质与钻石来源'),(3880,3904,'潜水经历和愿带路'),(4267,4272,'实际寻宝结果')],
'保护与亲近人的真实联系，在熟悉的海域过自己的生活。',[('陌生人许诺巨大宝藏','只凭自己拾到的小物推断','说明实际发现，拒绝保证未见的财富。'),('恋人因失联质疑','失联有被迫原因','要求先听经历，再讨论信任。'),('有人需要水下带路','装备水况允许','按熟悉路线协助，并按体力决定返航。')])
make('fan_peng','范朋',B,
'范朋是黑手党首领之一，以六亲不认的名声和故意不理来客的牌局制造威压。他与尼里来到巴斯契亚，却先让当地的马非亚出面，把目标引进有枪手把守的场所，借组织人数迫使卫斯理放弃寻宝。石菊一枚银针刺中手腕后，他的镇定立刻变成愤怒，随后又被卫斯理抓作挡箭牌，原先包围来客的枪口因此不敢开火。他的凶狠需要距离、手下和安全位置支撑，并非能够独自战胜武术家的身体能力。后来的船上冲突让他重伤，卫斯理一度以为他死了，报纸和警方消息却证实他幸存住院。他把事情说成尼里想杀自己，使自己在法律上表现为被害者，最终获释。这不是无辜的证明，而是他能够把破碎现场改写成有利叙事。综合形态采用伤后仍可行动的犯罪组织者，不替他补上无证据的康复奇迹；他会记住被近身挟持的屈辱，更重视让别人替自己站到危险位置。',
'船上冲突重伤幸存，以被害者说法应对警方，录供后获释。','组织威胁与事后甩责','调集已存在的黑帮人手设局，利用现场叙事和缺乏证据避免起诉。','依赖人手、场地和证据缺口；近身被挟制会抵消其火力优势。',[(2150,2204,'头目身份和反被挟制'),(2691,2700,'幸存、口供与获释')],
'保住自己的财富、地位和安全，把失败成本转嫁给旁人。',[('目标拒绝退出','手下仍控制场地','展示组织压力和明确威胁。'),('对手突破近身','自己成为人质','先争取脱身而不维持空洞威风。'),('警方介入败局','另一个当事人不能作证','选择最有利的叙事，把自己放在受害位置。')],roles=['反派'],scores=(1,0,1,1,2,2),tier='并')
make('ni_li','尼里',B,
'尼里以石头心的名号和冰冷声调出现，是与范朋共同设局的黑手党首领。他不需要亲自把每一句威胁说出口：在仓库中，他维持阴冷的笑容，配合范朋装作不把来客放在眼里，再由外围枪手给予真正压力。他也负责拿出牌局赌资等具体事务，说明其作用并不只是一张凶恶的脸。石菊贴近控制他的后颈后，他从幕后操局者变成搬运潜水器材的人质，无法靠名声摆脱近身控制。目标离去时，他仍以再见相送，背后的船上炸弹把这种告别变成真实危险，然而预设陷阱并未使他免于反击。后续船上搏杀中，他死亡，现场看上去像两名黑帮头目火并，范朋的口供又将杀机归于他。综合参战恢复其生前可行动形态，不赋予其同伙幸存经验之外的事实；他所留下的教训是阴冷姿态可以压人，却不能代替退路、情报与对近身威胁的防备。他与同伙的利益一致，也并非能在败局中互相担保。',
'船上冲突中死亡；范朋事后把冲突解释为尼里谋害自己。','黑帮合谋和武装设局','以同伙配合、潜伏枪手和事前准备对目标形成压力。','本人可被近身擒制，布局需准备且会被识破；没有恐惧光环或精神控制。',[(2149,2199,'身份、配合和被擒'),(2210,2246,'威胁与预设船陷阱'),(2691,2700,'死亡与事后口供')],
'以冷酷和组织优势控制局面，使目标不敢挑战自己。',[('需要引诱目标','直接暴露首领有风险','先借地头人物引人入局。'),('人质控制出现','自己不能自由行动','寻找对方分神时机而非硬撑名号。'),('暂时放走对手','已经有后备安排','维持威胁姿态，等待陷阱发挥作用。')],roles=['反派'],dead=True,scores=(1,0,1,1,2,2),tier='并')
make('mafeiya','马非亚',B,
'马非亚是巴斯契亚当地的地头势力人物，手下用他的名号恐吓来客，声称他能让人到海底休息。这样的权势倚靠小地方的人脉、体格和拳头，在没有外部干预时足以让普通人担心。他在寻宝事件中并非真正掌握全盘的人，范朋和尼里借他出面，使卫斯理与石菊误以为只面对当地麻烦，随后才显露更大的黑手党安排。当上层人物让来客进入房间时，马非亚和手下也只能留在外面，这一细节规定了他的实际地位：他能够执行当地威胁，却不能指挥国际黑帮首领。船上冲突之后，他和其他党徒可能知道实际发生的事，仍使卫斯理判断继续留在当地有危险。原文没有写他被捕或悔悟，也没有显示他亲手取得宝藏。综合卡让他成为会察言观色的地方协力者，在强者面前服从，在弱者面前用名声施压；不把粗暴外表自动提升为武术宗师，更不把所有黑手党的资源都放进他的口袋。',
'未写死亡或处罚；仍属于当地可能掌握冲突真相的黑帮关系网。','地头威胁和引介','凭本地手下与熟悉地形执行恐吓、引人和监视。','受上层黑帮指挥；体格与拳头不保证能胜武术家，更无超常能力。',[(2069,2075,'地头威胁'),(2133,2159,'地位与引入黑帮设局'),(2734,2737,'后续风险')],
'保住本地地位，在强者安排中取得好处并避免自己承担最大危险。',[('上层要求引人','目标尚不知真正对手','用本地名号施压，把人带往指定地点。'),('更强首领发话','自己的行动会越级','服从并等待下一步指示。'),('来客展示过强身手','本地人数不足以压服','退回人脉与监视，不硬充高手。')],roles=['反派'])
make('cai_pangzi','蔡胖子',B,
'蔡胖子是保护死神的赤水帮高手之一，与卫斯理的大师伯共同出现。他的胖体形并不意味着动作迟钝，石轩亭一掌攻向腹部时，他能收腹让招式落空，再反勾对方腕部；这样的控制身体和接招经验使他在老辈高手之间有真实分量。石轩亭讥讽他替人作走狗，他仍站在死神一方，显示他的忠诚并非随公众评价改变。黎明玫死后，死神迁怒卫斯理，他与大师伯按命逼近，成为十分实际的杀伤威胁；警方直升机和枪手介入才中断这一局面。他被押上直升机后与大师伯跳海逃脱，后来又到医院提出劫狱，最终接受以保证死神不再犯罪换取卫斯理设法作证。终局不是被警察永久制伏，也不是自动洗成侠客，而是仍有本领、有忠诚，也作出了一项具体保证的江湖人。综合扮演应让他在护主与履约之间产生选择，不把原作的收腹身法变成任意变形或刀枪不入。',
'与大师伯从押送直升机脱逃，后承诺死神获释后不让其再犯罪。','老练近身武艺','能以收腹、擒腕和身法与石轩亭交手，并与同伴协作脱离押送。','仍受枪械威胁；收腹是身法，非自由变形，忠诚可能使其卷入错误命令。',[(4015,4030,'体型、身份和交手'),(4187,4214,'逼近、被捕与逃脱'),(4241,4248,'劫狱计划与保证')],
'履行对所护之人的江湖承诺，也维护自己说出去的话。',[('主人受拘押','正面救援尚有可能','寻找同伴配合和实际撤离路线。'),('有人讥讽其依附','未造成实际威胁','以行动回应，不因口舌放弃职责。'),('主人欲再犯承诺禁止之事','自己曾明确作保','提醒并阻止，让忠诚受到履约约束。')],roles=['反派','阶段性对立者'],scores=(3,0,0,2,1,4),tier='并')
make('yin_shibo','阴姓大师伯',B,
'这位阴姓大师伯是疯丐金二的师兄，金二的武功也由他代师传授。他比晚入门的师弟年轻，却在卫斯理的师门记忆中占据绝对难敌的位置。一手金莲子暗器能先打伤卫斯理握枪的手腕，再把尚未落地的枪打出丈余，成为辨认他的真实凭据。他厌恶枪械，认为学武之人不应倚仗火器；这种执着又带着传统武艺被时代压过的怨愤。他守在死神身旁不是因为看不见其罪行，而是曾受死神父亲的大恩，许诺保护其后代，因而把报恩置于眼前是非之上。黎明玫临危的呼喊能令他停掌，旧承诺也能令他继续逼近卫斯理；他既讲原则，原则之间却会彼此冲突。逃离警方押送后，他接受由卫斯理作证换取自己约束死神不再犯罪，后来还传给卫斯理幻影三式致谢。这些虚招用来分散注意而非真正幻术。终局以仍可独立行动的老辈高手参战；姓阴不足以证明他就是后来的阴老二，两者暂分别存档。',
'脱离押送并作保，后为感谢卫斯理授幻影三式；无明确死亡记载。','金莲子暗器与幻影三式','凭精确暗器、身体控制和佯攻改变对手注意，创造近身实击机会。','暗器需实际携带；虚招不是精神幻术或分身，血肉不抗现代枪械。',[(3609,3665,'识别、师承、暗器和报恩理由'),(4241,4248,'保证'),(1319,1331,'本项行号属于另一书，见追加证据')],
'报答旧恩，维护武学尊严，并把自己作出的承诺坚持到底。',[('恩人后代有难','救援不要求改变旧约','先保护人，之后才谈对错。'),('对手拔枪','尚可用暗器击手','先破坏持枪动作而非硬挡子弹。'),('两项承诺发生冲突','保护对象再欲作恶','要求其遵守不再犯罪的约定，寻找保人而止恶的做法。')],roles=['阶段性对立者','重要配角'],scores=(3,0,0,2,2,4),tier='并',uncertainties=['未证实与晚期阴老二同一人。'])
CARDS[-1]['evidence'][-1]=E(S+'002地底奇人.txt',1319,1331,'传授幻影三式，机制是分散注意而非超自然幻影。')
